<template><div class="cpf-page-stack"><section class="cpf-card"><div class="cpf-card-head"><h1>Resilience 정책</h1><span class="cpf-status warning">2인 승인</span></div><p v-if="error" class="cpf-error" role="alert">{{ error }}</p><div class="cpf-toolbar"><input v-model.trim="query" placeholder="Operation ID"><button @click="search">검색</button></div><table class="cpf-table"><thead><tr><th>Operation</th><th>Revision</th><th>Timeout</th><th>Attempts</th></tr></thead><tbody><tr v-for="row in rows" :key="row.operationId"><td>{{ row.operationId }}</td><td>{{ row.revision }}</td><td>{{ row.timeoutBudget }}</td><td>{{ row.maxAttempts }}</td></tr><tr v-if="!rows.length"><td colspan="4">조회 결과가 없습니다.</td></tr></tbody></table></section><section class="cpf-card"><h2>정책 변경 요청</h2><div class="cpf-form-grid"><label>Operation ID<input v-model.trim="form.operationId"></label><label>Timeout ms<input v-model.number="form.timeoutMs" type="number"></label><label>Max Attempts<input v-model.number="form.maxAttempts" type="number"></label><label>Retry Backoff ms<input v-model.number="form.retryBackoffMs" type="number"></label><label>Circuit Threshold<input v-model.number="form.circuitFailureThreshold" type="number"></label><label>Circuit Open ms<input v-model.number="form.circuitOpenMs" type="number"></label><label>Bulkhead<input v-model.number="form.bulkheadMaxConcurrent" type="number"></label><label>Rate Permits<input v-model.number="form.rateLimitPermits" type="number"></label><label>Rate Window ms<input v-model.number="form.rateLimitWindowMs" type="number"></label><label>Idempotent<input v-model="form.idempotent" type="checkbox"></label><label>Unknown Reconcile<input v-model="form.unknownResultReconcileEnabled" type="checkbox"></label><label class="span-2">사유<input v-model.trim="form.reason"></label></div><button v-if="canRequest" class="primary" :disabled="busy" @click="requestPolicy">승인 요청</button><div class="cpf-form-grid"><label>Request ID<input v-model.trim="decision.requestId"></label><label>결정 사유<input v-model.trim="decision.reason"></label></div><div class="cpf-action-row"><button v-if="canApprove" :disabled="busy" @click="approve">승인</button><button v-if="canReject" class="danger" :disabled="busy" @click="reject">반려</button></div></section></div></template>
<script lang="ts">
import {defineComponent} from "vue";import {useAdmSessionStore} from "../../stores/admSessionStore";import{admResiliencePolicyApprove,admResiliencePolicyReject,admResiliencePolicyRequest,admResiliencePolicySearch}from"../../generated/cpf-api";type Policy={operationId:string;revision:number;timeoutBudget:string;maxAttempts:number};export default defineComponent({name:"ResiliencePoliciesPage",setup(){const session=useAdmSessionStore();return{session};},computed:{canRequest(){return this.session.hasButton("RESILIENCE_POLICY_REQUEST");},canApprove(){return this.session.hasButton("RESILIENCE_POLICY_APPROVE");},canReject(){return this.session.hasButton("RESILIENCE_POLICY_REJECT");}},data(){return{busy:false,error:"",query:"",rows:[] as Policy[],form:{operationId:"",timeoutMs:3000,maxAttempts:3,retryBackoffMs:100,circuitFailureThreshold:5,circuitOpenMs:30000,bulkheadMaxConcurrent:50,rateLimitPermits:100,rateLimitWindowMs:1000,idempotent:true,unknownResultReconcileEnabled:true,reason:""},decision:{requestId:"",reason:""}}},mounted(){void this.search();},methods:{async run<T>(a:()=>Promise<T>){this.busy=true;this.error="";try{return await a();}catch(e){this.error=e instanceof Error?e.message:String(e);return undefined;}finally{this.busy=false;}},async search(){this.rows=(await this.run(()=>admResiliencePolicySearch<Policy[]>({query:{query:this.query,page:0,size:100}})))??[];},async requestPolicy(){if(!this.canRequest)throw new Error("RESILIENCE_POLICY_REQUEST 권한이 없습니다.");const r=await this.run(()=>admResiliencePolicyRequest<{requestId:string}>({data:this.form}));if(r)this.decision.requestId=r.requestId;},async approve(){if(!this.canApprove)throw new Error("RESILIENCE_POLICY_APPROVE 권한이 없습니다.");await this.run(()=>admResiliencePolicyApprove({path:{requestId:this.decision.requestId},data:{reason:this.decision.reason},headers:{"X-CPF-Risk-Confirmed":"confirmed"}}));await this.search();},async reject(){if(!this.canReject)throw new Error("RESILIENCE_POLICY_REJECT 권한이 없습니다.");await this.run(()=>admResiliencePolicyReject({path:{requestId:this.decision.requestId},data:{reason:this.decision.reason},headers:{"X-CPF-Risk-Confirmed":"confirmed"}}));await this.search();}}});
</script>
